package imagesearch

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"unicode/utf8"

	"github.com/anthnel/devdesk/internal/oci"
)

const (
	// CatalogMaxPages is the number of catalog pages followed per walk.
	CatalogMaxPages = 10
	// CatalogPageSize is the number of names asked per page (?n=).
	CatalogPageSize = 1000
	// CatalogMaxRows is the number of rows one registry may show.
	CatalogMaxRows = 100
	// CatalogMinQueryRunes is the shortest query that walks a catalog.
	CatalogMinQueryRunes = 2
)

// CatalogLister walks a registry's catalog; oci.ListCatalogContext in production.
type CatalogLister func(ctx context.Context, apiURL, username, password string,
	maxPages, pageSize int) (names []string, truncated bool, err error)

// CatalogSearcher searches a private registry by walking /v2/_catalog and
// filtering names client-side; the query is never sent to the registry.
type CatalogSearcher struct {
	// List overrides oci.ListCatalogContext when set (tests).
	List CatalogLister
}

// Search implements Searcher.
func (c CatalogSearcher) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
	text := strings.TrimSpace(q.Text)
	if utf8.RuneCountInString(text) < CatalogMinQueryRunes {
		return nil, false, ErrQueryTooShort
	}
	list := c.List
	if list == nil {
		list = oci.ListCatalogContext
	}
	names, truncated, err := walkCatalog(ctx, t, list)
	if err != nil {
		return nil, false, err
	}
	if len(names) == 0 {
		return nil, truncated, nil
	}
	prefix := strings.Trim(t.RepoPrefix, "/")
	needle := strings.ToLower(text)
	var all []Image
	sawPrefix := false
	for _, name := range names {
		rest := name
		if prefix != "" {
			var ok bool
			if rest, ok = strings.CutPrefix(name, prefix+"/"); !ok {
				continue
			}
			sawPrefix = true
		}
		if !validRepoPath(name) {
			continue
		}
		if strings.Contains(strings.ToLower(rest), needle) {
			all = append(all, Image{EntryKey: t.EntryKey, Name: rest, Repo: name})
		}
	}
	if prefix != "" && !sawPrefix {
		if truncated {
			return nil, true, nil
		}
		return nil, false, fmt.Errorf("%w (prefix %q)", ErrPrefixNotInCatalog, prefix)
	}
	slices.SortStableFunc(all, func(a, b Image) int {
		if d := MatchTier(text, a.Name) - MatchTier(text, b.Name); d != 0 {
			return d
		}
		if d := strings.Compare(strings.ToLower(a.Name), strings.ToLower(b.Name)); d != 0 {
			return d
		}
		return strings.Compare(a.Repo, b.Repo)
	})
	limit := CatalogMaxRows
	if q.Limit > 0 && q.Limit < limit {
		limit = q.Limit
	}
	cut := len(all) > limit
	if cut {
		all = all[:limit]
	}
	return all, truncated || cut, nil
}
package imagesearch

import (
	"errors"

	"github.com/anthnel/devdesk/internal/oci"
)

// Verdict is one registry's answer to a search. The zero value is not a
// verdict: it means no answer yet, and Classify never returns it.
type Verdict int

const (
	// VerdictOK means rows were found.
	VerdictOK Verdict = iota + 1
	// VerdictNoResult means the registry answered and nothing matches.
	VerdictNoResult
	// VerdictRefused means unsupported or refused.
	VerdictRefused
	// VerdictFailed means network, deadline, 5xx, 429 or unreadable body.
	VerdictFailed
)

// String is the verdict as shown to the user.
func (v Verdict) String() string {
	switch v {
	case VerdictOK:
		return "ok"
	case VerdictNoResult:
		return "no result"
	case VerdictRefused:
		return "unsupported or refused"
	case VerdictFailed:
		return "failed"
	}
	return "pending"
}

// Outcome is a verdict and its marks. Invariant: Partial is set only with ok
// or no result (a partial walk that found nothing is still "no result"), never
// with refused or failed.
type Outcome struct {
	Verdict Verdict
	Partial bool
	Skipped bool
}

// ErrQueryTooShort: the catalog was not walked, the query is too short.
var ErrQueryTooShort = errors.New("query too short to walk a catalog")

// ErrPrefixNotInCatalog: no catalog name carries the entry's prefix.
var ErrPrefixNotInCatalog = errors.New("no catalog name carries the entry's prefix")

// Classify turns a search answer (error, row count, partial flag) into one
// Outcome. An error always wins over n and partial. With no error, n == 0
// keeps the Partial mark: the verdict is "no result" and Partial is set when
// the walk was cut short.
func Classify(err error, n int, partial bool) Outcome {
	switch {
	case err == nil && n == 0:
		return Outcome{Verdict: VerdictNoResult, Partial: partial}
	case err == nil:
		return Outcome{Verdict: VerdictOK, Partial: partial}
	case errors.Is(err, ErrQueryTooShort):
		return Outcome{Verdict: VerdictNoResult, Skipped: true}
	case errors.Is(err, ErrUnsupported), errors.Is(err, ErrPrefixNotInCatalog):
		return Outcome{Verdict: VerdictRefused}
	}
	var se *oci.StatusError
	if errors.As(err, &se) && refusedStatus(se) {
		return Outcome{Verdict: VerdictRefused}
	}
	return Outcome{Verdict: VerdictFailed}
}

// refusedStatus tells a refusal from a failure: the registry refusing the
// request (401, 403, 404, 405) or the token endpoint refusing the credentials
// (401, 403). Any other status, 429 and 5xx included, is a failure.
func refusedStatus(se *oci.StatusError) bool {
	switch se.Code {
	case 401, 403:
		return true
	case 404, 405:
		return se.Source != oci.SourceToken
	}
	return false
}
