	// SourceRegistry is the registry's v2 API.
	SourceRegistry StatusSource = iota
	// SourceToken is the Bearer token endpoint.
	SourceToken
	// SourceManagementAPI is a registry manager's own REST API (Nexus
	// /service/rest), not the distribution v2 API.
	SourceManagementAPI
)

// StatusError is a registry, token or management API endpoint answering with a
// non-success status. Failures that are not a status (unreadable body, missing
// realm, no token field) are plain errors.
type StatusError struct {
	Code   int
	Source StatusSource
	// Challenge is the Www-Authenticate header of a 401 whose challenge is not
	// Bearer; empty otherwise.
	Challenge string
	// unexpectedChallenge tells that 401 apart from a 401 answered after a
	// token exchange, so Error() keeps both historical messages.
	unexpectedChallenge bool
}

// Error returns the message the plain errors carried before the type existed.
func (e *StatusError) Error() string {
	switch {
	case e.Source == SourceToken:
		return fmt.Sprintf("token endpoint returned %d", e.Code)
	case e.Source == SourceManagementAPI:
		return fmt.Sprintf("management API returned %d", e.Code)
	case e.unexpectedChallenge:
		return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
	}
	return fmt.Sprintf("registry returned %d", e.Code)
}

// ListRegistryTags lists the tags of a repository through the registry's v2 API.
//
// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
// realm's token endpoint — the flow Docker Hub and most hosted registries use.
// The token is kept for the following pages.
//
// The list is followed across pages: whatever a registry caps a response at,
// and Docker Hub does not, a repository with more tags than one page holds is
// returned whole. This is the one tag lister that speaks the Bearer flow; the
// template client's ListTags (Client.ListTags) reads a registry the user
// configured for templates and only ever sends Basic auth.
func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
	return ListRegistryTagsContext(context.Background(), apiURL, repo, username, password)
}
// pageSize names per page and following Link rel="next" for at most maxPages
// pages. truncated is true when the walk stopped with names left: page cap
// reached with a next link, more than maxPages*pageSize names, or a next link
// to another origin (never followed: the Basic credentials and the token are
// not sent to it). HTTP 3xx redirects follow registryHTTPClient, which refuses
// off-origin ones (RefuseOffOriginRedirect, DEVDESK-410).
// Authentication is the tag flow's (Basic, then Bearer on a challenge, token
// kept across pages); a non-200 answer is a *StatusError.
func ListCatalogContext(ctx context.Context, apiURL, username, password string, maxPages, pageSize int) (names []string, truncated bool, err error) {
	if maxPages <= 0 || pageSize <= 0 {
		return nil, false, fmt.Errorf("catalog walk needs positive limits, got %d pages of %d", maxPages, pageSize)
	}
	next := strings.TrimSuffix(apiURL, "/") + "/v2/_catalog?n=" + strconv.Itoa(pageSize)
	token := ""
	for page := 0; next != ""; page++ {
		if page == maxPages {
			return names, true, nil
		}
		body, link, usedToken, err := registryGETBoundedContext(ctx, next, username, password, token, maxCatalogPage)
		if err != nil {
			return nil, false, err
		}
		token = usedToken
		var result struct {
			Repositories []string `json:"repositories"`
		}
		if err := json.Unmarshal(body, &result); err != nil {
			return nil, false, fmt.Errorf("decode catalog response: %w", err)
		}
		names = append(names, result.Repositories...)
		if len(names) > maxPages*pageSize {
			return names[:maxPages*pageSize], true, nil
		}
		current := next
		if next = resolveNext(current, link); next != "" && !sameOrigin(current, next) {
			return names, true, nil
		}
	}
	return names, false, nil
}

