func (s *Server) handler(routes []route) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id, known := identify(r)
		if known {
			if rt, ok := match(routes, r.Method, r.URL.RequestURI(), id); ok {
